from sys import stdin, stdout
import math

MOD = 1000000007

def mod_inverse(a, m):
    return pow(a, m-2, m)

def ncr(n, k):
    if k > n:
        return 0
    num = denom = 1
    for i in range(k):
        num = num * (n - i) % MOD
        denom = denom * (i + 1) % MOD
    return num * mod_inverse(denom, MOD) % MOD

def solve():
    N = int(stdin.readline())
    A = list(map(int, stdin.readline().split()))

    dp = [0] * (N + 1)
    dp[0] = 1

    for a in A:
        ndp = [0] * (N + 1)
        for j in range(N + 1):
            ndp[j] = (ndp[j] + dp[j]) % MOD
            if j > 0:
                ndp[min(j + a, N)] = (ndp[min(j + a, N)] + dp[j]) % MOD
        dp = ndp

    ans = 0
    for i in range(1, N + 1):
        ans = (ans + i * dp[i]) % MOD

    stdout.write(str(ans) + '\n')

if __name__ == "__main__":
    solve()

import sys
from fractions import Fraction

MOD = 1000000007

def expected_lis_length(N, A):
    dp = [Fraction(1, 1)] * (N + 1)

    for a in A:
        new_dp = [Fraction(0, 1)] * (N + 1)
        for j in range(N, -1, -1):
            if j == N:
                new_dp[j] = Fraction(1, 1)
            else:
                total_prob = 0
                for k in range(j + 1, min(j + a, N + 1)):
                    total_prob += dp[k]
                new_dp[j] = (total_prob + Fraction(dp[j], 1)) * Fraction(1, a)
        dp = new_dp

    result = sum(dp) * Fraction(1, N)
    return int(result.numerator * pow(result.denominator, MOD - 2, MOD) % MOD)

